function psqlExec(sql: string): void {
  const dir = mkdtempSync(join(tmpdir(), 'ipns-gate-'));
  const file = join(dir, 'q.sql');
  writeFileSync(file, sql + '\n');
  try {
    execSync(`PGPASSWORD=REDACTED psql -h localhost -U postgres -d ${PSQL_DB} -f "${file}"`, {
      encoding: 'utf8',
      stdio: ['pipe', 'pipe', 'pipe'],
    });
  } finally {
    try {
      unlinkSync(file);
    } catch {
      /* ignore */
    }
    try {
      rmdirSync(dir);
    } catch {
      /* ignore */
    }
  }
}

